using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using OrcaFacil.Application.Abstractions;using OrcaFacil.Domain.Entities;using OrcaFacil.Persistence;
namespace OrcaFacil.Web.Pages.AccountAdmin;[Authorize(Policy="AccountAdmin")]public sealed class IndexModel(OrcaFacilDbContext db,ICurrentAccountService current):PageModel{public int ActiveUsers{get;private set;}public int ActiveModules{get;private set;}public decimal Mrr{get;private set;}public async Task<IActionResult>OnGetAsync(CancellationToken ct){if(current.AccountId is not Guid id)return Forbid();ActiveUsers=await db.AccountMembers.CountAsync(x=>x.AccountId==id&&!x.IsDeleted&&x.Status==OrcaFacil.Domain.Enums.AccountMemberStatus.Active,ct);var active=db.AccountModuleSubscriptions.Where(x=>x.AccountId==id&&!x.IsDeleted&&x.Status==SaasModuleSubscriptionStatus.Active);ActiveModules=await active.CountAsync(ct);Mrr=await active.SumAsync(x=>(decimal?)(x.BillingPeriod==SaasBillingPeriod.Annual?x.ContractedPrice/12:x.ContractedPrice-x.DiscountAmount),ct)??0;return Page();}}
